// Regenerates source/api/schema.d.ts from the OpenAPI spec served by your Pi-hole.
// Usage: npm run schema
import "dotenv/config";
import { writeFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";

const apiUrl = process.env["API_URL"];
if (!apiUrl) {
	throw new Error("API_URL is not set. Add it to .env first.");
}

const specUrl = new URL(`${apiUrl}/docs/specs/main.yaml`);
const ast = await openapiTS(specUrl);

const header = `/**
 * This file was auto-generated by openapi-typescript (npm run schema).
 * Do not make direct changes to the file.
 */

`;

await writeFile("source/api/schema.d.ts", header + astToString(ast));
console.log("Schema generated from your Pi-hole's API spec.");
